namespace ghidra.app.plugin.core.compositeeditor;







using docking;
using docking.action;
using generic.theme;
using ghidra.util.exception;

/**
 * Action for use in the composite data type editor.
 * This action has help associated with it.
 */
public class MoveUpAction : CompositeEditorTableAction {

	private static Icon ICON = new GIcon("icon.plugin.composite.editor.move.up");
	public static string ACTION_NAME = "Move Components Up";
	private static string GROUP_NAME = COMPONENT_ACTION_GROUP;
	private static string DESCRIPTION = "Move selected components up";
	private static string[] POPUP_PATH = new string[] { ACTION_NAME };

	private static KeyStroke KEY_STROKE =
		KeyStroke.getKeyStroke(KeyEvent.VK_UP, InputEvent.ALT_DOWN_MASK);

	public MoveUpAction(CompositeEditorProvider<object,object> provider) : base(provider, ACTION_NAME, GROUP_NAME, POPUP_PATH, null, ICON)
    {
		setDescription(DESCRIPTION);
		setKeyBindingData(new KeyBindingData(KEY_STROKE));
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		if (!isEnabledForContext(context)) {
			return;
		}
		try {
			model.moveUp();
		}
		catch (UsrException e1) {
			model.setStatus(e1.getMessage(), true);
		}
		requestTableFocus();
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		return !hasIncompleteFieldEntry() && model.isMoveUpAllowed();
	}

}
